        */
        enum TxnState {
            COMMITTED = 1,
            ABORTED = 2,
            OPEN = 3,
        }

        enum LockLevel {
            DB = 1,
            TABLE = 2,
            PARTITION = 3,
        }

        enum LockState {
            /**
            requester has the lock
            */
            ACQUIRED = 1,
            /**
            requester is waiting for the lock and should call checklock at a later point to see if the lock has been
            obtained.
            */
            WAITING = 2,
            /**
            the lock has been aborted, most likely due to timeout
            */
            ABORT = 3,
            /**
            returned only with lockNoWait, indicates the lock was not available and was not acquired
            */
            NOT_ACQUIRED = 4,
        }

        enum LockType {
            SHARED_READ = 1,
            SHARED_WRITE = 2,
            EXCLUSIVE = 3,
            EXCL_WRITE = 4,
