            REVOKE = 2,
        }

        enum DataOperationType {
            SELECT = 1,
            INSERT = 2,
            UPDATE = 3,
            DELETE = 4,
            /**
            this is the default to distinguish from NULL from old clients
            */
            UNSET = 5,
            /**
            drop table, insert overwrite, etc - something non-transactional
            */
            NO_TXN = 6,
        }

        /**
        Types of events the client can request that the metastore fire.  For now just support DML operations, as the
        metastore knows
        about DDL operations and there's no reason for the client to request such an event.
        */
        enum EventRequestType {
            INSERT = 1,
            UPDATE = 2,
            DELETE = 3,
