        // ═════════════════════════ topology ═════════════════════════

        // Calls the services (Left side).
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Client : Host { }

        // Implements the services (Right side).
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Server : Host { }

        interface ClientServer : Connects<Client, Server> {

            /**
            Thrift service FacebookService
            Standard base service
            */
            interface FacebookService {
                (L____________, fb303.FacebookService_getName_Result) getName(fb303.FacebookService_getName_Args req);
                (L____________, fb303.FacebookService_getVersion_Result) getVersion(fb303.FacebookService_getVersion_Args req);
                (L____________, fb303.FacebookService_getStatus_Result) getStatus(fb303.FacebookService_getStatus_Args req);
                (L____________, fb303.FacebookService_getStatusDetails_Result) getStatusDetails(fb303.FacebookService_getStatusDetails_Args req);
                (L____________, fb303.FacebookService_getCounters_Result) getCounters(fb303.FacebookService_getCounters_Args req);
                (L____________, fb303.FacebookService_getCounter_Result) getCounter(fb303.FacebookService_getCounter_Args req);
                (L____________, fb303.FacebookService_setOption_Result) setOption(fb303.FacebookService_setOption_Args req);
                (L____________, fb303.FacebookService_getOption_Result) getOption(fb303.FacebookService_getOption_Args req);
                (L____________, fb303.FacebookService_getOptions_Result) getOptions(fb303.FacebookService_getOptions_Args req);
                (L____________, fb303.FacebookService_getCpuProfile_Result) getCpuProfile(fb303.FacebookService_getCpuProfile_Args req);
                (L____________, fb303.FacebookService_aliveSince_Result) aliveSince(fb303.FacebookService_aliveSince_Args req);
                // oneway reinitialize(): see state FacebookService_reinitialize of the connection
                // oneway shutdown(): see state FacebookService_shutdown of the connection
            }

            /**
            Thrift service ThriftHiveMetastore
            This interface is live.
            extends fb303.FacebookService: its methods are declared below as well.
            */
            interface ThriftHiveMetastore {
                (L____________, ThriftHiveMetastore_abort_Compactions_Result) abort_Compactions(ThriftHiveMetastore_abort_Compactions_Args req);
                (L____________, ThriftHiveMetastore_getMetaConf_Result, MetaException) getMetaConf(ThriftHiveMetastore_getMetaConf_Args req);
                (L____________, ThriftHiveMetastore_setMetaConf_Result, MetaException) setMetaConf(ThriftHiveMetastore_setMetaConf_Args req);
                (L____________, ThriftHiveMetastore_create_catalog_Result, AlreadyExistsException, InvalidObjectException, MetaException) create_catalog(ThriftHiveMetastore_create_catalog_Args req);
                (L____________, ThriftHiveMetastore_alter_catalog_Result, NoSuchObjectException, InvalidOperationException, MetaException) alter_catalog(ThriftHiveMetastore_alter_catalog_Args req);
                (L____________, ThriftHiveMetastore_get_catalog_Result, NoSuchObjectException, MetaException) get_catalog(ThriftHiveMetastore_get_catalog_Args req);
                (L____________, ThriftHiveMetastore_get_catalogs_Result, MetaException) get_catalogs(ThriftHiveMetastore_get_catalogs_Args req);
